parameters.jsCode:
return $input.all().map(item => {
  const l = item.json;
  return {
    json: {
      'Business Name': l['Business Name'] ?? l.name ?? null,
      'Phone': l['Phone'] ?? l.phone ?? null,
      'Email': l['Email'] ?? l.email ?? null,
      'Website': l['Website'] ?? l.website ?? null,
      'Lead Tier': l['Lead Tier'] ?? l.lead_tier ?? null,   // delete this line if you don't want the tag
    }
  };
});

const items = $input.all();

// Works whether each item is one business or an array of businesses
const businesses = items.flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);

const first = (arr) => (Array.isArray(arr) && arr.length ? arr[0] : null);

// Remove ?utm_... and other query strings from URLs
const cleanUrl = (url) => {
  if (!url) return null;
  try {
    const u = new URL(url);
    return (u.origin + u.pathname).replace(/\/$/, '');
  } catch {
    return url;
  }
};

const seen = new Set();
const results = [];

for (const b of businesses) {
  // Skip closed businesses and duplicates
  if (b.permanentlyClosed || b.temporarilyClosed) continue;
  if (!b.placeId || seen.has(b.placeId)) continue;
  seen.add(b.placeId);

  const emails = [...new Set((b.emails || []).map(e => e.trim().toLowerCase()))];
  const dist = b.reviewsDistribution || {};
  const totalReviews = b.reviewsCount || 0;
  const negativeReviews = (dist.oneStar || 0) + (dist.twoStar || 0);
  const negativePct = totalReviews
    ? Math.round((negativeReviews / totalReviews) * 1000) / 10
    : null;

  const daysOpen = (b.openingHours || []).filter(h => !/closed/i.test(h.hours)).length;

  const lead = {
    name: (b.title || '').trim(),
    category: b.categoryName || null,
    services: (b.categories || []).join(', '),
    address: b.address || null,
    neighborhood: b.neighborhood || null,
    city: b.city || null,
    state: b.state || null,
    postal_code: b.postalCode || null,
    phone: b.phone || null,
    email: emails[0] || null,
    all_emails: emails.join(', '),
    website: cleanUrl(b.website),
    domain: b.domain || null,
    instagram: first(b.instagrams),
    facebook: first(b.facebooks),
    linkedin: first(b.linkedIns),
    twitter: first(b.twitters),
    tiktok: first(b.tiktoks),
    youtube: first(b.youtubes),
    rating: b.totalScore ?? null,
    reviews_count: totalReviews,
    negative_reviews_pct: negativePct,
    days_open_per_week: daysOpen,
    hours: (b.openingHours || []).map(h => `${h.day}: ${h.hours}`).join(' | '),
    latitude: b.location?.lat ?? null,
    longitude: b.location?.lng ?? null,
    google_maps_url: b.url || null,
    place_id: b.placeId,
    search_query: b.searchString || null,
    scraped_at: b.scrapedAt || null,
  };

  // Simple lead score (max 100), adjust the weights to your niche
  let score = 0;
  if (lead.email) score += 30;
  if (lead.phone) score += 10;
  if (lead.website) score += 10;
  if (lead.instagram) score += 10;
  if (lead.rating >= 4.5) score += 10;
  if (lead.reviews_count >= 100) score += 10;
  if (lead.reviews_count >= 500) score += 10;
  if (lead.negative_reviews_pct >= 5) score += 10; // possible pain point to pitch

  lead.lead_score = score;
  lead.lead_tier = score >= 70 ? 'Hot' : score >= 40 ? 'Warm' : 'Cold';

  results.push({ json: lead });
}

return results;

// Change 'Switch' to your Switch node's name and 1 to the output feeding the HTTP Request
const leads = $('Routes leads').all(1);

const BAD = /(\.(png|jpe?g|gif|svg|webp|avif|ico|css|js|woff2?|ttf|pdf)$)|^(noreply|no-reply|donotreply|mailer-daemon|postmaster|sentry)@|(example\.com|domain\.com|sentry\.io|wixpress\.com|godaddy\.com)$/i;

const findEmail = (html) => {
  const text = html.replace(/&#64;|&commat;/g, '@').replace(/&amp;/g, '&');
  const found = new Set();
  for (const m of text.matchAll(/mailto:([^"'?>\s]+)/gi)) found.add(decodeURIComponent(m[1]).toLowerCase());
  for (const m of text.matchAll(/[a-z0-9._%+-]+@[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,}/gi)) found.add(m[0].toLowerCase());
  return [...found].find(e => !BAD.test(e) && !/@\d+x\./.test(e)) || null;
};

return $input.all().map((item, i) => {
  const j = item.json || {};
  const l = leads[item.pairedItem?.item ?? i]?.json || {};
  const base = {
    business_name: l['Business Name'] ?? l.name ?? l.title ?? null,
    website: l['Website'] ?? l.website ?? null,
  };

  // Blocked or failed request: keep a short summary, drop the HTML
  const raw = typeof j.data === 'string' ? j.data : (j.body || j.details?.body || '');
  const blocked = j.error || j.details || j.httpCode || /Just a moment\.\.\./.test(raw);
  if (blocked) {
    return { json: {
      ...base,
      email: null,
      status: 'blocked',
      http_code: j.details?.httpCode || j.httpCode || j.error?.status || null,
      reason: /challenges\.cloudflare\.com/.test(raw + (j.details?.description || ''))
        ? 'Cloudflare challenge' : (j.details?.message || j.error?.message || 'Request failed').slice(0, 80),
    } };
  }

  const email = findEmail(raw);
  return { json: { ...base, email, status: email ? 'ok' : 'no_email_found', http_code: 200, reason: null } };
});

