{
  "type": "object",
  "properties": {
    "business_name": {
      "type": "string",
      "description": "Exact business name from the input"
    },
    "detail_used": {
      "type": "string",
      "description": "The single exact fact from the input that the line is based on, quoted with its numbers, e.g. '4.9 rating from 139 reviews'. Never a label like 'Quick note'."
    },
    "first_line": {
      "type": "string",
      "description": "One or two sentences, under 40 words, using only facts from the input"
    }
  },
  "required": ["business_name", "detail_used", "first_line"]
}
